/**
 * Manages hover interactions across multiple chart instances.
 *
 * Each mounted chart calls `useChartHoverState(chartId)`. Hover state can be kept
 * local to a single chart or synchronized across every mounted instance, controlled
 * by the `syncHover` / `syncTooltip` preferences which persist to localStorage so the
 * choice survives page reloads.
 */

const HOVER_SYNC_STORAGE_KEY = 'supabase-chart-hover-sync-enabled'
const TOOLTIP_SYNC_STORAGE_KEY = 'supabase-chart-tooltip-sync-enabled'

export interface ChartHoverState {
  /** Index of the hovered data point, or null when nothing is hovered. */
  hoveredIndex: number | null
  /** Id of the chart currently driving the hover, or null when nothing is hovered. */
  hoveredChart: string | null
  /** True when a data point is hovered (for this chart, or any chart when synced). */
  isHovered: boolean
  /** True only for the chart instance that originated the hover. */
  isCurrentChart: boolean
  /** Whether hover state is synchronized across all chart instances. */
  syncHover: boolean
  /** Whether tooltip state is synchronized across all chart instances. */
  syncTooltip: boolean
}

export interface UseChartHoverStateReturn extends ChartHoverState {
  setHover: (index: number | null) => void
  clearHover: () => void
  setSyncHover: (enabled: boolean) => void
  setSyncTooltip: (enabled: boolean) => void
}

interface GlobalHoverState {
  hoveredIndex: number | null
  hoveredChart: string | null
  syncHover: boolean
  syncTooltip: boolean
}

/**
 * Reads a boolean sync preference from localStorage. Falls back to `defaultValue`
 * (and warns) when the value is missing, non-parseable, or otherwise corrupted.
 */
function readSyncSetting(key: string, defaultValue: boolean): boolean {
  if (typeof window === 'undefined') return defaultValue

  try {
    const stored = window.localStorage.getItem(key)
    if (stored === null) return defaultValue

    const parsed = JSON.parse(stored)
    return typeof parsed === 'boolean' ? parsed : defaultValue
  } catch (error) {
    console.warn('Failed to read chart hover sync setting from localStorage:', error)
    return defaultValue
  }
}

/**
 * Persists a boolean sync preference to localStorage. Storage failures are swallowed
 * and warned about so that in-memory state can still be updated by the caller.
 */
function writeSyncSetting(key: string, value: boolean): void {
  if (typeof window === 'undefined') return

  try {
    window.localStorage.setItem(key, JSON.stringify(value))
  } catch (error) {
    console.warn('Failed to save chart hover sync setting to localStorage:', error)
  }
}

// Shared, module-level state so that every hook instance can react to the same hover
// and synchronization preferences. Sync preferences are seeded from localStorage.
const globalHoverState: GlobalHoverState = {
  hoveredIndex: null,
  hoveredChart: null,
  syncHover: readSyncSetting(HOVER_SYNC_STORAGE_KEY, true),
  syncTooltip: readSyncSetting(TOOLTIP_SYNC_STORAGE_KEY, true),
}

const listeners = new Set<() => void>()

const notifyListeners = () => {
  listeners.forEach((listener) => listener())
}

export function useChartHoverState(chartId: string): UseChartHoverStateReturn {
  // Bumped to force a re-render whenever the shared global state changes.
  const [, forceRender] = useState(0)
  // Per-instance hover state used when hover synchronization is disabled.
  const [localHover, setLocalHover] = useState<{
    hoveredIndex: number | null
    hoveredChart: string | null
  }>({ hoveredIndex: null, hoveredChart: null })

  useEffect(() => {
    const listener = () => forceRender((tick) => tick + 1)
    listeners.add(listener)
    return () => {
      listeners.delete(listener)
    }
  }, [])

  const setHover = useCallback(
    (index: number | null) => {
      const nextChart = index === null ? null : chartId

      if (globalHoverState.syncHover) {
        globalHoverState.hoveredIndex = index
        globalHoverState.hoveredChart = nextChart
        notifyListeners()
      } else {
        setLocalHover({ hoveredIndex: index, hoveredChart: nextChart })
      }
    },
    [chartId]
  )

  const clearHover = useCallback(() => {
    if (globalHoverState.syncHover) {
      globalHoverState.hoveredIndex = null
      globalHoverState.hoveredChart = null
      notifyListeners()
    } else {
      setLocalHover({ hoveredIndex: null, hoveredChart: null })
    }
  }, [])

  const setSyncHover = useCallback((enabled: boolean) => {
    // Disabling hover sync also disables tooltip sync.
    const nextSyncTooltip = enabled ? globalHoverState.syncTooltip : false

    // Always attempt to persist so the preference survives reloads, even when the
    // in-memory value is unchanged.
    writeSyncSetting(HOVER_SYNC_STORAGE_KEY, enabled)
    writeSyncSetting(TOOLTIP_SYNC_STORAGE_KEY, nextSyncTooltip)

    // Skip the state update entirely when nothing actually changed.
    if (
      globalHoverState.syncHover === enabled &&
      globalHoverState.syncTooltip === nextSyncTooltip
    ) {
      return
    }

    globalHoverState.syncHover = enabled
    globalHoverState.syncTooltip = nextSyncTooltip
    notifyListeners()
  }, [])

  const setSyncTooltip = useCallback((enabled: boolean) => {
    // Enabling tooltip sync requires hover sync to be enabled as well.
    const nextSyncHover = enabled ? true : globalHoverState.syncHover

    writeSyncSetting(TOOLTIP_SYNC_STORAGE_KEY, enabled)
    writeSyncSetting(HOVER_SYNC_STORAGE_KEY, nextSyncHover)

    if (
      globalHoverState.syncTooltip === enabled &&
      globalHoverState.syncHover === nextSyncHover
    ) {
      return
    }

    globalHoverState.syncTooltip = enabled
    globalHoverState.syncHover = nextSyncHover
    notifyListeners()
  }, [])

  const syncHover = globalHoverState.syncHover
  const syncTooltip = globalHoverState.syncTooltip

  // When hover is synced, all instances read the shared state; otherwise each
  // instance reflects only its own local hover.
  const hoveredIndex = syncHover ? globalHoverState.hoveredIndex : localHover.hoveredIndex
  const hoveredChart = syncHover ? globalHoverState.hoveredChart : localHover.hoveredChart

  return {
    hoveredIndex,
    hoveredChart,
    isHovered: hoveredIndex !== null,
    isCurrentChart: hoveredChart === chartId,
    syncHover,
    syncTooltip,
    setHover,
    clearHover,
    setSyncHover,
    setSyncTooltip,
  }
}
